class Solution {
public:
    int minActivationCost(vector<vector<int>>& edges, vector<int>& values) {
        int n = values.size();
        const long long INF = (1LL<<60);
        vector<int> parity(n);
        for (int i = 0; i < n; ++i) {
            parity[i] = (__builtin_popcountll(values[i]) & 1); // 0 = even, 1 = odd
        }

        vector<long long> best1(n, INF), best2(n, INF);
        long long ans = INF;

        for (auto &e : edges) {
            int u = e[0], v = e[1];
            long long c = e[2];
            if (parity[u] == parity[v]) {
                if (c < ans) ans = c;               // single edge balanced
            } else {
                // update for u
                if (c < best1[u]) {
                    best2[u] = best1[u];
                    best1[u] = c;
                } else if (c < best2[u]) {
                    best2[u] = c;
                }
                // update for v
                if (c < best1[v]) {
                    best2[v] = best1[v];
                    best1[v] = c;
                } else if (c < best2[v]) {
                    best2[v] = c;
                }
            }
        }

        for (int i = 0; i < n; ++i) {
            if (parity[i] == 0 && best2[i] != INF) {
                long long cand = best1[i] + best2[i];
                if (cand < ans) ans = cand;
            }
        }

        return (ans == INF) ? -1 : (int)ans;
    }
};
